        uint256 trueBorrowValue = lending.getBorrowValue(amountToBorrow);
        uint256 trueMaxBorrowValue = trueCollateralValue * 100 / 175;

        // Position is now undercollateralized: true borrow value exceeds max borrow value
        assertTrue(trueBorrowValue > trueMaxBorrowValue, "Position undercollateralized");
        // Health factor < 1: (collateral * 100) < (borrow * 175)
        assertTrue(trueCollateralValue * 100 < trueBorrowValue * 175, "Health factor < 1");
